function heldoutJobState(j){return String(j.execution_state??j.state??j.worker_status??j.backend_state??j.status??'').toLowerCase();}
function heldoutJobCounts(jobs){
 const states=jobs.map(heldoutJobState);
 return {running:states.filter(s=>s==='running').length,pending:states.filter(s=>/^(pending|queued)$/.test(s)).length,
 assigned:states.filter(s=>/^(assigned|staging|launching|fetch|upload)$/.test(s)).length,
 unknown:states.filter(s=>!(/^(running|assigned|staging|launching|fetch|upload|pending|queued|complete|completed|synced|failed|cancelled|retired)$/.test(s))).length};
}
function renderHeldout(d){
 const h=d.heldout_recovery??{}, rows=h.rows??[], src=d.sources.heldout_recovery??{};
 $('heldout-observation').innerHTML=observation('Held-out deficit audit',h.observed_at,!!src.available,src.error,300);
 const jobs=new Map();for(const r of rows)for(const j of (Array.isArray(r.active_jobs)?r.active_jobs:[])){if(j&&typeof j==='object')jobs.set(String(j.job_id??j.id??JSON.stringify(j)),j);}
 const {running,pending,assigned,unknown}=heldoutJobCounts([...jobs.values()]);
 const stats=[['Model holdout accepted',counts(d).eval_model,'Target 891'],['Category / room accepted',counts(d).eval_category,'Target 109'],['Unfinished quota rows',src.available?rows.filter(r=>r.remaining>0).length:null,'Class / task and strict bucket deficits'],['Running held-out jobs',src.available?running:null,'Execution reported by the dated scheduler or worker observation; no acceptance inferred'],['Pending held-out jobs',src.available?pending:null,'Queued separately from running'],['Assigned / staging held-out jobs',src.available?assigned:null,'Allocation, startup or transfer is not verified native execution'],['Jobs awaiting backend observation',src.available?unknown:null,'A submitted controller record does not prove scheduler pending'],['Deficits under investigation',src.available?rows.filter(r=>r.remaining>0&&r.flat_progress_investigation).length:null,'Flat progress requires an explicit next action']];
 $('heldout-summary').innerHTML=stats.map(([title,v,caption])=>`<article class="metric"><h3>${esc(title)}</h3><div class="value">${n(v)}</div><p class="caption">${esc(caption)}</p></article>`).join('');
 $('heldout-owner').textContent='Accountable workstream owner: '+(h.owner??'Awaiting authoritative ledger')+'. '+(h.activity_semantics??'Active engineering and persistent controllers are reported separately.');
 const split=$('heldout-split').value,state=$('heldout-state').value,q=$('heldout-search').value.toLowerCase();
 const filtered=rows.filter(r=>{const activity=heldoutJobCounts(Array.isArray(r.active_jobs)?r.active_jobs:[]);return (split==='all'||r.split===split)&&(state==='all'||state==='deficit'&&r.remaining>0||state==='flat'&&r.flat_progress_investigation||state==='failed'&&failed(r.state)||state==='running'&&activity.running>0||state==='assigned'&&activity.assigned>0||state==='pending'&&activity.pending>0)&&(!q||JSON.stringify(r).toLowerCase().includes(q));});
 $('heldout-rows').innerHTML=filtered.map(r=>`<tr><td class="name">${esc(splitNames[r.split]??r.split)}<div>${esc(r.class_id??r.task)}</div><div class="small-label">${esc(r.task)} · bucket ${esc(r.bucket??'task quota')}</div></td><td>${n(r.accepted)} / ${n(r.target)}<div class="bar"><span style="width:${Math.min(100,Math.max(0,(r.accepted??0)/(r.target||1)*100))}%"></span></div><div class="small-label">${n(r.remaining)} remaining · ${pct(num(r.accepted),r.target)}</div></td><td>${pill(r.state??'Unavailable',failed(r.state)?'bad':r.remaining>0?'warn':'')}<p>${esc(r.owner??'Unassigned')}</p>${r.flat_progress_investigation?pill('Flat progress: investigate','warn'):''}</td><td class="reason">${esc(plain(r.blocker))}<p><strong>Next:</strong> ${esc(plain(r.next_action))}</p></td><td class="reason">${esc(plain(r.active_jobs??[]))}<p>${esc(plain(r.controller??[]))}</p><div class="small-label">Last accepted ${date(r.last_accepted_at)}<br>Last progress ${date(r.last_progress_at)}</div></td><td><details><summary>Configuration / runtime / failures</summary><pre class="recovery-evidence">${esc(JSON.stringify({configuration:r.configuration,runtime:r.runtime,failures:r.failures,investigation:r.flat_progress_investigation,evidence:r.evidence},null,2))}</pre></details></td></tr>`).join('')||'<tr><td colspan="6">No matching held-out observations available. Missing evidence is not zero deficit.</td></tr>';
}
for(const id of ['heldout-split','heldout-state','heldout-search'])$(id).addEventListener(id==='heldout-search'?'input':'change',()=>current&&renderHeldout(current));

let preparationOffset=0,preparationRequest=0;
